const persistDeliverySnapshot = `-- name: PersistDeliverySnapshot :execrows
UPDATE business_report_deliveries AS delivery
SET report_body_snapshot = $2, report_fingerprint = $3, updated_at = now()
WHERE delivery.id = $1 AND delivery.report_body_snapshot IS NULL
  AND EXISTS (SELECT 1 FROM business_report_runs AS run
    WHERE run.id = delivery.run_id AND run.id = $4
      AND run.lease_owner = $5 AND run.lease_generation = $6
      AND run.status IN ('pending', 'retry'))
`

type PersistDeliverySnapshotParams struct {
	ID                 pgtype.UUID `json:"id"`
	ReportBodySnapshot pgtype.Text `json:"report_body_snapshot"`
	ReportFingerprint  []byte      `json:"report_fingerprint"`
	ID_2               pgtype.UUID `json:"id_2"`
	LeaseOwner         pgtype.Text `json:"lease_owner"`
	LeaseGeneration    int64       `json:"lease_generation"`
}

func (q *Queries) PersistDeliverySnapshot(ctx context.Context, arg PersistDeliverySnapshotParams) (int64, error) {
	result, err := q.db.Exec(ctx, persistDeliverySnapshot,
		arg.ID,
		arg.ReportBodySnapshot,
		arg.ReportFingerprint,
		arg.ID_2,
		arg.LeaseOwner,
		arg.LeaseGeneration,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

